const ym = new Date(Date.now()-5*864e5).toISOString().slice(0,7);
const prev = new Date(new Date().setMonth(new Date().getMonth()-2)).toISOString().slice(0,7);
const rows = items.map(i=>i.json);
return [{ json: { month: ym, thisMonth: rows.filter(r=>(r.Date||'').startsWith(ym)), lastMonth: rows.filter(r=>(r.Date||'').startsWith(prev)) } }];
